css:
/* The Dark Lord: a black nebula, a wedge-shaped ship overhead, a red blade and red edges. */

.min-h-screen.surface-fond {
  background-image: linear-gradient(90deg, color-mix(in srgb, var(--surface-fond) 94%, transparent) 0%, color-mix(in srgb, var(--surface-fond) 80%, transparent) 45%, color-mix(in srgb, var(--surface-fond) 25%, transparent) 100%), var(--image-vador);
  background-size: cover, cover;
  background-position: center, right center;
  background-repeat: no-repeat;
  background-attachment: fixed;
}

.surface-carte { background-color: color-mix(in srgb, var(--surface-carte) 84%, transparent); }
.surface-carte.rounded-xl, .surface-carte.rounded-2xl, .surface-carte.rounded-lg { border: 1px solid rgba(255, 255, 255, 0.10); box-shadow: 0 0 18px rgba(255, 30, 40, 0.10); }
[data-app-menubar] { background-color: var(--surface-carte); }
[role="dialog"] { box-shadow: 0 0 0 1px rgba(255, 30, 40, 0.6), 0 0 32px rgba(255, 30, 40, 0.35); }
.surface-carte.rounded-xl, .surface-carte.rounded-2xl {
  background-image: linear-gradient(#ff3b3b, #ff3b3b), linear-gradient(#ff3b3b, #ff3b3b), linear-gradient(#ff3b3b, #ff3b3b), linear-gradient(#ff3b3b, #ff3b3b);
  background-size: 16px 2px, 2px 16px, 16px 2px, 2px 16px;
  background-position: left top, left top, right bottom, right bottom;
  background-repeat: no-repeat;
}
/* The menu keeps the shop's colour; over it, a red band behind the name, the Dark Lord on his ridge, faint red scanlines. */
.surface-menu {
  background-image: linear-gradient(180deg, rgba(200, 16, 32, 0.18) 0, rgba(200, 16, 32, 0) 110px), var(--image-menu), repeating-linear-gradient(0deg, rgba(200, 16, 32, 0.05) 0 1px, transparent 1px 4px), linear-gradient(180deg, color-mix(in srgb, var(--surface-menu) 88%, #ffffff), var(--surface-menu));
  background-size: 100% 110px, 100% auto, auto, auto;
  background-position: center top, center bottom, center top, center top;
  background-repeat: no-repeat, no-repeat, repeat, no-repeat;
  border-right: 2px solid rgba(220, 20, 40, 0.8);
  animation: sw-empire-hum 3.2s ease-in-out infinite;
}
[data-nav-title] { color: #d0142a; text-transform: uppercase; letter-spacing: 0.24em; font-size: 10px; font-weight: 800; text-shadow: 0 0 10px rgba(255, 40, 40, 0.35); }
[aria-current="page"] { box-shadow: inset 3px 0 0 #ff2a2a, inset 24px 0 24px -12px rgba(255, 30, 30, 0.35); }
[data-app-menubar] { border-bottom: 1px solid rgba(255, 40, 50, 0.5); }
/* Module names in the menu: a fine red glow around the letters. */
[data-nav-row-face] { text-shadow: 0 0 8px rgba(255, 40, 50, 0.3); }
/* Icons in imperial medallions: a thin red ring and glow; the open page's is lit, white on red. */
[data-nav-icon] { padding: 4px; border-radius: 8px; color: #d0142a; border: 1px solid rgba(208, 20, 42, 0.5); background-color: rgba(208, 20, 42, 0.08); box-shadow: 0 0 10px rgba(255, 30, 40, 0.2), inset 0 0 6px rgba(255, 30, 40, 0.12); }
[aria-current="page"] [data-nav-icon] { color: #ffffff; background-color: #d0142a; border-color: #ff4a5a; box-shadow: 0 0 14px rgba(255, 30, 40, 0.65); }
h1 { text-transform: uppercase; letter-spacing: 0.16em; font-weight: 300; text-shadow: 0 0 14px rgba(255, 40, 40, 0.5); }
@keyframes sw-empire-hum {
  0%, 100% { box-shadow: 1px 0 14px rgba(255, 30, 40, 0.25); }
  50% { box-shadow: 1px 0 28px rgba(255, 30, 40, 0.55); }
}
@media (prefers-reduced-motion: reduce) { .surface-menu { animation: none; } }
